@php($id=($record?->id ? $record->id.'-' : 'new-').$field)
@if($field === 'journal_volume_id')<select class="portal-select" id="{{ $id }}" name="{{ $field }}">@foreach($volumes as $volume)<option value="{{ $volume->id }}" @selected(old($field,$record?->journal_volume_id)==$volume->id)>Volume {{ $volume->number }} ({{ $volume->year }})</option>@endforeach</select>
@elseif(isset($choices[$field]))<select class="portal-select" id="{{ $id }}" name="{{ $field }}">@foreach($choices[$field] as $value=>$label)<option value="{{ $value }}" @selected(old($field,$record?->{$field})===$value)>{{ $label }}</option>@endforeach</select>
@elseif(in_array($field,['biography','description','body']))<textarea class="portal-textarea" id="{{ $id }}" name="{{ $field }}" rows="6">{{ old($field,$record?->{$field}) }}</textarea>
@elseif(in_array($field,['photo','logo','cover']))<input class="portal-input" id="{{ $id }}" name="{{ $field }}" type="file" accept="image/jpeg,image/png,image/webp">@if($record?->{match($field){'cover'=>'cover_image_path', default=>$field.'_path'}})<small class="portal-help">Current file retained unless replaced.</small>@endif
@else<input class="portal-input" id="{{ $id }}" name="{{ $field }}" @if(str_contains($field,'date')) type="date" value="{{ old($field,$record?->{$field}?->format('Y-m-d') ?? '') }}" @else value="{{ old($field,$record?->{$field}) }}" @endif @required(in_array($field,$required))>@endif
